"""Seating charts laid out as rows of text."""

import rosterkit.models


def seating_rows(students, seats_per_row):
    """One line per row, students sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError(
            'seats per row must be positive: {}'.format(seats_per_row)
        )
    ordered = sorted(
        students,
        key=lambda s: (s.last_name.casefold(), s.first_name.casefold()),
    )
    if not ordered:
        raise ValueError('no students to seat')
    lines = []
    for start in range(0, len(ordered), seats_per_row):
        names = [
            s.display_name
            for s in ordered[start:start + seats_per_row]
        ]
        lines.append('Row {}: {}'.format(
            start // seats_per_row + 1, ' | '.join(names)
        ))
    return lines
