cat > tests/test_seating.py <<'EOF'
import unittest

import rosterkit.models
import rosterkit.seating


def make(last, first):
    return rosterkit.models.Student('1', last, first, 'A')


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make('Halloway', 'Juno'),
            make('Zane', 'Ola'),
            make('Dunmere', 'Piet'),
        ]

    def test_sorted_and_split_into_rows(self):
        rows = rosterkit.seating.seating_rows(self.students, 2)
        self.assertEqual(rows, [
            'Row 1: Dunmere, Piet | Halloway, Juno',
            'Row 2: Zane, Ola',
        ])

    def test_first_name_breaks_ties(self):
        rows = rosterkit.seating.seating_rows(
            [make('Ng', 'Bo'), make('Ng', 'Al')], 5
        )
        self.assertEqual(rows, ['Row 1: Ng, Al | Ng, Bo'])

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows(self.students, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows([], 3)
